INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q1', 'Which of the following is not true?', '["The tighter the security, the lower the network performance", "The security design and application has no effect on the performance", "Multi-layer security can be a bottleneck to the IT assets access", "The tighter the security, the higher the protection of the network"]', 'The security design and application has no effect on the performance', 'Security mechanisms always impact system performance because they consume resources such as CPU and memory. Therefore, saying security has no effect on performance is incorrect.', 'Computer Ethics', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q2', 'A relation R with X→WZ is in full functional dependency (2NF). Which of the following violates it?', '["WYZ are non-prime attributes and are determined by the primary attribute X", "Removing X from X→WXYZ returns the relation R to first normal form", "From X→WYZ, removing any of the WYZ does not affect the second normal form", "From X→WZ, R can possibly have duplicate values"]', 'Removing X from X→WXYZ returns the relation R to first normal form', 'Removing the determinant (X) breaks the dependency relationship. This does not correctly describe normalization and violates the concept of 2NF.', 'Database', 'hard', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q3', 'One of the following policy is used by queue data structure', '["LILO", "FILO", "LIFO", "None"]', 'D) None', 'Queue uses FIFO (First In First Out), which is not listed in the options.', 'Data Structures', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q4', 'Use case diagram in software development model demonstrate', '["Functional requirement of the system", "Functional and non-functional requirement of the system", "Performance requirement of the system", "Non-functional requirement of the system"]', 'Functional requirement of the system', 'Use case diagrams describe system interactions and functionality, which represent functional requirements.', 'Software Engineering', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q5', 'The basic computer instruction format with 16 bits, which of the following is not true?', '["Register reference type instruction contains 12 bits", "Address mode contains 1 bit", "The opcode contains 3 bits", "The opcode contains 4 bit"]', 'The opcode contains 4 bit', 'In a 16-bit instruction format, the opcode is typically 3 bits, not 4 bits.', 'Computer Architecture', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q6', 'Which of the following IP is used as a loop back service?', '["198.168.0.1", "127.0.0.1", "0.0.0.0", "255.255.255.255"]', 'B) 127.0.0.1', '127.0.0.1 is the loopback address used to refer to the local machine.', 'Networking', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q7', 'What will be the path if we use depth-first search strategy?
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q8', 'A micro-instruction is designed to specify none or one of three operations of one kind and up to six operations of another kind. Minimum number of bits required?', '["2 bit", "4 bit", "8 bit", "6 bit"]', 'C) 8 bit', '2 bits are needed for 3 operations and 3 bits for 6 operations, plus control bits, totaling 8 bits.', 'Computer Architecture', 'hard', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q9', 'What will be the final result in queue after the following operations?
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q10', 'Which of the following is not true about software maintenance?', '["Maintenance is software testing", "Maintenance is used to change existing system", "Maintenance is used to add new requirements", "Maintenance is used to fix errors"]', 'Maintenance is software testing', 'Software maintenance involves fixing, updating, and improving systems, not testing.', 'Software Engineering', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q11', 'During normalization, which cannot hold?', '["First normal form is created by creating new relation from weak attributes", "Second normal form is created by decomposing relation for each partial key", "Boyce Codd Normal Form is created from strict third normal form", "Third normal form removes transitive dependency"]', 'First normal form is created by creating new relation from weak attributes', '1NF ensures atomic values and removes repeating groups. It is not about creating relations from weak attributes.', 'Database', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q12', 'In a wait-for graph, an edge from P1 to Pj signifies that ______', '["P1 is waiting for Pj to release a resource", "Pj is waiting for P1 to leave the system", "P1 is waiting for Pj to leave the system", "Pj is waiting for P1 to release a resource"]', 'P1 is waiting for Pj to release a resource', 'In a wait-for graph, an edge P1 → Pj means P1 is waiting for a resource held by Pj.', 'Operating Systems', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q13', 'Given A = 0 and B unknown, which statement is true?', '["A + B = 1", "A ⊕ B = 0", "A + B = 0", "A · B = 1"]', 'A + B = 0', 'With A = 0, OR operation gives A + B = B. The expected answer assumes B = 0 case, though the question is ambiguous.', 'Digital Logic', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q14', 'Which SQL statement creates a new table employee(empID varchar(10))?', '["add new employee(varchar(10)) as table", "insert table employee(empID varchar(10))", "create table employee(empID varchar(10))", "add table employee(empID varchar(10))"]', 'create table employee(empID varchar(10))', 'Correct SQL syntax is CREATE TABLE table_name (column datatype).', 'Database', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q15', 'Which protocol automatically assigns IP addresses to clients?', '["ARP", "RARP", "NAT", "DHCP"]', 'DHCP', 'DHCP dynamically assigns IP addresses to devices in a network.', 'Networking', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
