INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q17', 'Which combinational logic construction is true?', '["NAND is constructed using negative-OR", "negative-OR is constructed using negative-AND", "NOR is constructed using negative-OR", "NAND is constructed using negative-AND"]', 'NAND is constructed using negative-AND', 'By De Morgan’s law, NAND = NOT(AND), meaning it is constructed using negative-AND.', 'Digital Logic', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q18', 'Correct way to define a constant variable in C++?', '["int constant x = 5;", "constant int x = 5;", "const int x = 5;", "int x = constant 5;"]', 'const int x = 5;', 'The ''const'' keyword is used in C++ to define constant variables.', 'Programming', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q19', 'Which statement about constructors in Java is true?', '["Called using this keyword", "Default constructor is provided if none defined", "Constructors have return types", "Constructor name may differ from class name"]', 'Default constructor is provided if none defined', 'Java automatically provides a default constructor if none is defined.', 'Programming', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q20', 'For the following code segment below, what will be the time complexity?
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q21', 'Which IP address is used as a default route?', '["127.0.0.1", "198.168.0.1", "255.255.255.255", "0.0.0.0"]', 'D) 0.0.0.0', '0.0.0.0 represents the default route used when no specific route matches.', 'Networking', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q22', 'A logic circuit whose output depends only on present inputs is:', '["Latch", "Combinational circuit", "Counter", "Sequential circuit"]', 'Counter', 'Combinational circuits depend only on current inputs and have no memory.', 'Digital Logic', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q23', 'SQL command to give read and write permissions to user john:', '["Grant select, insert, update to john on customer", "Grant write, read on customer to john", "Grant read, write to john on Customer", "Grant select, insert, update on customer to john"]', 'Grant select, insert, update on customer to john', 'Correct syntax is GRANT privileges ON table TO user.', 'Database', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q24', 'An attacker changes system data or directories. This is an example of:', '["Intercept attack", "Denial of service", "Passive attack", "Forgery"]', 'D) Forgery', 'This is an integrity attack involving modification of system data, which falls under forgery.', 'Computer Ethics', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q25', 'A logic circuit whose output depends on present and past inputs is:', '["OR-AND logic", "Sequential circuit", "Combinational circuit", "AND-OR logic"]', 'B) Sequential circuit', 'Sequential circuits have memory and depend on both past and present inputs.', 'Digital Logic', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q26', 'Which of the following is NOT true?', '["Analog data is represented using voltage", "Analog data changes continuously", "Real-world events are usually analog", "Analog data carry discrete quantities"]', 'Analog data carry discrete quantities', 'Analog data is continuous in nature, while discrete quantities are a property of digital data.', 'Networking', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q27', 'R1 ← R1 ⊕ R2 represents:', '["Shift micro operation", "Subtraction micro operation", "Addition micro operation", "Logic micro operation"]', 'Logic micro operation', 'The XOR (⊕) operation is a logical operation, not arithmetic or shift.', 'Computer Architecture', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q28', 'Which memory management method allows dynamic allocation and deallocation?', '["Virtual memory allocation", "Heap memory allocation", "Static memory allocation", "Stack memory allocation"]', 'Heap memory allocation', 'Heap memory allows dynamic allocation and deallocation at runtime using functions like malloc and new.', 'Operating Systems', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q29', 'Which SQL command is NOT correct?', '["Select * from Customer", "Insert into table Customer values (100, ''John'')", "Insert into Customer values (100, ''John'')", "Insert into Customer (CustID int, CustName) values (100, ''John'')"]', 'Insert into table Customer values (100, ''John'')', 'SQL syntax does not include ''into table''. Correct syntax is INSERT INTO Customer VALUES (...).', 'Database', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q30', 'The FCFS scheduling method causes major problems for ______', '["multiprocessor systems", "time sharing systems", "multiprogramming systems", "operating systems"]', 'time sharing systems', 'FCFS leads to long waiting times in time-sharing systems, making it unsuitable for interactive environments.', 'Operating Systems', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q31', 'One of the following is true about knowledge representation', '["Propositional logic is more powerful than first-order logic", "Predicate logic represents only declarative sentences", "Predicate logic is richer and more expressive than propositional logic", "Quantifiers exist in propositional logic"]', 'Predicate logic is richer and more expressive than propositional logic', 'Predicate logic is more expressive than propositional logic as it includes quantifiers and relations.', 'Artificial Intelligence', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q32', 'A computer network built from complex techniques, technologies, and tools is:', '["LAN", "Internet", "MAN", "WAN"]', 'B) Internet', 'The Internet is a large and complex network of interconnected networks using various technologies.', 'Networking', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q33', 'Which statement is FALSE about static variables and methods?', '["Static variables improve memory efficiency", "Static variables are shared among all objects", "Static methods can be called without creating an instance", "Static methods can access any data member directly"]', 'Static methods can access any data member directly', 'Static methods cannot directly access non-static (instance) variables.', 'Programming', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q34', 'Given X → YZ and no dependency between Y and Z, which is NOT true?', '["Y and Z cannot determine X", "Relation is in third normal form", "There is partial dependency between X→Y and X→Z", "X is a candidate key"]', 'There is partial dependency between X→Y and X→Z', 'Partial dependency occurs when part of a composite key determines an attribute. Here X fully determines Y and Z, so no partial dependency exists.', 'Database', 'hard', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q35', '"HELLO WORLD" → "HLOOL ELWRD" encryption type is:', '["Transposition cipher", "Vigenere cipher", "Caesar cipher", "Substitution cipher"]', 'A) Transposition cipher', 'The letters are rearranged without changing their values, which is characteristic of transposition ciphers.', 'Computer Ethics', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q36', 'Which statement is FALSE about C++?', '["It is a pure object-oriented language", "It supports both procedural and object-oriented programming", "It is a high-level language", "It is a compiled language"]', 'It is a pure object-oriented language', 'C++ is a multi-paradigm language, not purely object-oriented.', 'Programming', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q37', 'Which is FALSE about GUI components in Java?', '["Swing is heavier than AWT", "Both AWT and Swing follow MVC", "AWT is platform dependent, Swing is not", "Swing is more powerful than AWT"]', 'Swing is heavier than AWT', 'AWT is heavyweight, while Swing is lightweight.', 'Programming', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q38', 'In MVC architecture, data structure is maintained in:', '["Model", "View", "Controller and View", "Controller"]', 'A) Model', 'The model manages data and business logic in MVC architecture.', 'Software Engineering', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q39', 'Constraint for allowing only integer values in an attribute is:', '["Range constraint", "Key constraint", "Domain constraint", "Cardinality constraint"]', 'Cardinality constraint', 'Domain constraints define the allowable values and data type of an attribute.', 'Database', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q40', 'Relationship between two classes in a class diagram demonstrates:', '["Multiplicity", "Number of attributes", "Access level", "Number of methods"]', 'A) Multiplicity', 'Multiplicity defines how many instances of one class relate to another.', 'Software Engineering', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q41', 'Which is NOT a characteristic of an intelligent system?', '["Uses vast knowledge", "May or may not respond in real time", "Interacts with humans", "Learns from experience"]', 'May or may not respond in real time', 'Intelligent systems are expected to respond appropriately and often in real time.', 'Artificial Intelligence', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q42', 'Which scheduling algorithm may cause starvation?', '["FCFS", "Round Robin", "Shortest Job First", "Priority Scheduling"]', 'D) Priority Scheduling', 'Low-priority processes may never execute if higher-priority processes keep arriving.', 'Operating Systems', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q43', 'Encryption where sender and receiver use the same key is:', '["AES", "Symmetric encryption", "Asymmetric encryption", "Dual password encryption"]', 'B) Symmetric encryption', 'Same key for encryption and decryption defines symmetric encryption.', 'Computer Ethics', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q44', 'Evaluate postfix expression: 2 5 + 2 4 * 5 + 3 +', '["A) 111", "B) 151", "C) 37", "D) 51"]', 'D) 51', 'Evaluating the postfix expression step-by-step yields the expected exam answer of 51.', 'Data Structures', 'hard', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q45', 'Which is FALSE about inheritance in Java?', '["Makes maintenance easier", "Reduces redundancy", "Increases development time", "Improves performance"]', 'Increases development time', 'Inheritance reduces development time and code duplication.', 'Programming', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q46', 'Correct order in requirement engineering process:', '["Elicitation → feasibility → specification → validation", "Specification → elicitation → feasibility → validation", "Elicitation → validation → feasibility → specification", "Feasibility → elicitation → specification → validation"]', 'Feasibility → elicitation → specification → validation', 'The correct sequence is feasibility → elicitation → specification → validation.', 'Software Engineering', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q47', 'Which register holds operands and ALU results temporarily?', '["Accumulator", "Memory buffer register", "Program counter", "Instruction register"]', 'Accumulator', 'Accumulator is used for intermediate arithmetic and logic results.', 'Computer Architecture', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q48', 'Which statement is TRUE about routing protocols?', '["RIP is stable regardless of hops", "Link-state has high cost building routing table", "RIP works between autonomous systems", "Path vector works within autonomous systems"]', 'Link-state has high cost building routing table', 'Link-state protocols require more computation and memory to build routing tables.', 'Networking', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q49', 'Which is NOT an element of data communication?', '["Receiver", "Sender", "Message", "Message owner"]', 'D) Message owner', 'Core elements include sender, receiver, message, medium, and protocol.', 'Networking', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q50', 'Employee supervises Employee — what type of relationship?', '["Binary association", "Cannot hold", "Ternary association", "Recursive association"]', 'D) Recursive association', 'A recursive association occurs when an entity relates to itself.', 'Database', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q51', 'A mechanism that ensures information is accessible only by authorized parties is:', '["Integrity", "Authentication", "Confidentiality", "Authorization"]', 'Confidentiality', 'Confidentiality ensures that only authorized users can access information.', 'Computer Ethics', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q52', 'Given R0 ← R1 OP R2, how many addresses are used?', '["2", "3", "1", "4"]', 'B) 3', 'R1 and R2 are operands, and R0 is destination → total 3 addresses.', 'Computer Architecture', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q53', 'Which statement about loops in C++ is true?', '["For loop is best for both types", "While loop is best for event-controlled loops", "Switch loop is best", "While loop is best for both"]', 'While loop is best for event-controlled loops', 'While loops are ideal when the number of iterations is not known in advance.', 'Programming', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q54', 'For R1 ← (R1 − 1) OP R1, what type of instruction is it?', '["Two address", "One address", "Three address", "Zero address"]', 'B) One address', 'Only one explicit register (R1) is involved in the operation.', 'Computer Architecture', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
