INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q56', 'Which statement is FALSE about knowledge representation?', '["Propositional logic includes objects and relations", "Propositional logic becomes impractical for large systems", "Propositional logic represents facts", "First-order logic includes objects and relations"]', 'Propositional logic includes objects and relations', 'Propositional logic only represents facts, not objects or relationships.', 'Artificial Intelligence', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
