INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q58', 'Which is NOT a property of growth-rate functions?', '["Ignore low-order terms", "Ignore multiplicative constants", "O(f(n)) + O(g(n)) = O(f(n)+g(n))", "None"]', 'D) None', 'All listed are valid properties of asymptotic analysis.', 'Algorithms', 'medium', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
