INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q62', 'Which is NOT true about digital representation?', '["High precision", "Versatile", "Highly affected by noise", "Uses discrete values"]', 'Highly affected by noise', 'Digital systems are less affected by noise compared to analog systems.', 'Digital Logic', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
