INSERT INTO questions (id, question, options, answer, explanation, topic, difficulty, source) VALUES ('exit-2017-q76', 'Which of the following is FALSE about arrays in C++?', '["Elements can be accessed randomly", "Stored in contiguous memory", "Can be part of a structure", "Size can be decided at runtime"]', 'Size can be decided at runtime', 'Standard C++ arrays require compile-time size. Dynamic sizing uses vectors or dynamic allocation.', 'Programming', 'easy', 'Exit Exam 2017') ON CONFLICT (id) DO UPDATE SET question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explanation = EXCLUDED.explanation, topic = EXCLUDED.topic, difficulty = EXCLUDED.difficulty, source = EXCLUDED.source;
